"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type SnapLaneItem = {
  id: string;
  title: string;
  description?: string;
};

export type SnapLaneProps = {
  items: SnapLaneItem[];
  className?: string;
};

/**
 * Horizontal swipe lane with snap points and peek of the next card.
 */
function SnapLane({ items, className }: SnapLaneProps) {
  const ref = React.useRef<HTMLDivElement>(null);

  return (
    <div className={cn("w-full", className)}>
      <div
        ref={ref}
        className="flex snap-x snap-mandatory gap-3 overflow-x-auto pb-2 [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        {items.map((item, i) => (
          <article
            key={item.id}
            className="w-[78%] shrink-0 snap-center rounded-2xl border border-border bg-card p-5 shadow-[var(--shadow-soft)] sm:w-[56%]"
            style={{
              backgroundImage: `linear-gradient(145deg, color-mix(in oklch, var(--color-chart-${(i % 5) + 1}) 14%, transparent), transparent 55%)`,
            }}
          >
            <div className="text-[11px] font-medium text-muted-foreground">
              {String(i + 1).padStart(2, "0")}
            </div>
            <h3 className="mt-2 text-lg font-semibold tracking-tight">
              {item.title}
            </h3>
            {item.description ? (
              <p className="mt-2 text-sm text-muted-foreground">
                {item.description}
              </p>
            ) : null}
          </article>
        ))}
      </div>
      <p className="mt-1 text-center text-[11px] text-muted-foreground">
        Swipe to snap
      </p>
    </div>
  );
}

export { SnapLane };
